method below_zero(operations: seq<int>) returns (result: bool)
    requires |operations| > 0 // The operations list should not be empty
    ensures result <==> (Exists i :: 0 <= i < |operations| && (Sum(operations[0..i+1]) < 0))
    ensures !result <==> (forall i :: 0 <= i < |operations| ==> (Sum(operations[0..i+1]) >= 0))
{
    var balance := 0;
    result := false;

    // Iterate through the operations to check the balance
    foreach op in operations {
        balance := balance + op;
        if balance < 0 {
            result := true;
            return;
        }
    }
    return;
}
```

